PriceRecord _price(String id, double buy, double quote, double min, double max,
    List<double> values) {
  final now = DateTime(2026, 9, 17, 9);
  return PriceRecord(
    priceId: 'DEMO-PUNE-$id',
    materialId: id,
    location: 'Pune, Maharashtra',
    updatedAt: now,
    buyingPrice: buy,
    quotedPrice: quote,
    marketMin: min,
    marketMax: max,
    unit: 'kg',
    recyclerId: 'DEMO-R-001',
    history: List.generate(
        values.length,
        (index) =>
            PricePoint(now.subtract(Duration(days: 6 - index)), values[index])),
  );
}

